state.kills=0;player.root.position.set(0,0,3.7);boss.root.position.set(0,0,-3.3);boss.root.rotation.set(0,0,0);boss.body.scale.set(1,1,1);updateUI()}

// Impact effects
const effects=[];
const sparkGeo=new THREE.SphereGeometry(.055,6,5);
function burst(point,color=0xffbd63,count=12,power=2){for(let i=0;i<count;i++){const m=mesh(sparkGeo,mat(color,.35,0,color,1.2),scene,point.toArray());m.castShadow=false;const v=new THREE.Vector3((Math.random()-.5)*power,Math.random()*power*.8,(Math.random()-.5)*power);effects.push({m,v,life:.45+Math.random()*.38,max:.8});}}
function shockRing(position,color=0xff433e,radius=2.8){const ring=mesh(new THREE.TorusGeometry(radius,.075,8,48),mat(color,.3,.1,color,1.4),scene,[position.x,.12,position.z],[-Math.PI/2,0,0]);effects.push({m:ring,life:.45,max:.45,ring:true});}
const dangerMat=new THREE.MeshBasicMaterial({color:0xff2e48,transparent:true,opacity:.22,depthWrite:false,side:THREE.DoubleSide});
const danger=mesh(new THREE.CircleGeometry(2.9,48),dangerMat,scene,[0,.07,0],[-Math.PI/2,0,0]);danger.visible=false;
const targetRing=mesh(new THREE.TorusGeometry(1.05,.035,6,48),mat(0xffc36a,.35,.2,0xff8b31,1.5),scene,[0,.08,0],[-Math.PI/2,0,0]);targetRing.visible=false;
function actAttack(){if(!state.running||state.attackCd>0)return;state.attackCd=.54;player.body.rotation.x=-.14;player.arms[1].rotation.x=-1.05;player.sword.rotation.x=-.65;const dx=boss.root.position.x-player.root.position.x,dz=boss.root.position.z-player.root.position.z;const dist=Math.hypot(dx,dz);if(dist<3.35){const bonus=state.bossMode==='recover'?1.55:1;const damage=12*bonus;state.bossHp=Math.max(0,state.bossHp-damage);state.kills++;burst(boss.root.position.clone().add(new THREE.Vector3(0,2.4,.4)),state.bossMode==='recover'?0xffd57a:0xff734a,17,2.5);announce(state.bossMode==='recover'?'ABERTURA!':'ACERTO');if(state.bossHp<=0){updateUI();endGame(true);return;}if(state.bossHp<55&&state.phase===1){state.phase=2;announce('AZHUR DESPERTA');}updateUI();}else{burst(player.root.position.clone().add(new THREE.Vector3(0,1.5,-.4)),0xffffff,4,.65)}}
function actDodge(){if(!state.running||state.dodgeCd>0)return;state.dodge=.43;state.dodgeCd=1.05;state.invuln=.48;const move=getMove();let dx=move.x,dz=move.y;if(Math.hypot(dx,dz)<.1){dx=player.root.position.x-boss.root.position.x;dz=player.root.position.z-boss.root.position.z;let n=Math.hypot(dx,dz)||1;dx/=n;dz/=n}player.root.position.x+=dx*1.1;player.root.position.z+=dz*1.1;player.root.position.x=THREE.MathUtils.clamp(player.root.position.x,-4.25,4.25);player.root.position.z=THREE.MathUtils.clamp(player.root.position.z,-1.2,6);}
function actHeal(){if(!state.running||state.healCd>0||state.heals<=0||state.hp>=100)return;state.heals--;state.healCd=1.1;state.hp=Math.min(100,state.hp+34);burst(player.root.position.clone().add(new THREE.Vector3(0,1,0)),0x70ffd0,18,1.7);announce('CHAMA RESTAURADA');updateUI()}
function getMove(){let x=0,y=0;if(keys.has('KeyA')||keys.has('ArrowLeft'))x-=1;if(keys.has('KeyD')||keys.has('ArrowRight'))x+=1;if(keys.has('KeyW')||keys.has('ArrowUp'))y-=1;if(keys.has('KeyS')||keys.has('ArrowDown'))y+=1;x+=moveStick.x;y+=moveStick.y;const l=Math.hypot(x,y);if(l>1){x/=l;y/=l}return{x,y}}
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(e.repeat)return;if(e.code==='Space'||e.code==='KeyJ')actAttack();if(e.code==='ShiftLeft'||e.code==='ShiftRight'||e.code==='KeyK')actDodge();if(e.code==='KeyQ'||e.code==='KeyE')actHeal();if(e.code==='Escape'&&state.running){state.running=false;document.querySelector('#intro').classList.remove('hidden')}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
document.querySelector('#startBtn').addEventListener('click',startGame);document.querySelector('#restartBtn').addEventListener('click',startGame);
document.querySelector('#attackBtn').addEventListener('pointerdown',e=>{e.preventDefault();actAttack()});document.querySelector('#dodgeBtn').addEventListener('pointerdown',e=>{e.preventDefault();actDodge()});document.querySelector('#healBtn').addEventListener('pointerdown',e=>{e.preventDefault();actHeal()});
const stick=document.querySelector('#stick'),knob=document.querySelector('#knob');let stickPointer=null;
stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(stickPointer);moveStick={x:0,y:0};updateStick(e)});
stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)updateStick(e)});
function updateStick(e){const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=e.clientX-cx,dy=e.clientY-cy;const max=r.width*.34,d=Math.hypot(dx,dy);if(d>max){dx*=max/d;dy*=max/d}knob.style.transform=`translate(${dx}px,${dy}px)`;moveStick={x:dx/max,y:dy/max}}
function releaseStick(e){if(e.pointerId===stickPointer){stickPointer=null;moveStick={x:0,y:0};knob.style.transform='translate(0,0)'}}stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);

let last=performance.now();function animate(now){requestAnimationFrame(animate);const dt=Math.min(.04,(now-last)/1000);last=now;const t=now/1000;
// Ambient motion
embers.forEach((e,i)=>{e.m.position.y=e.baseY+Math.sin(t*e.speed+e.phase)*e.amp;e.m.position.x+=Math.sin(t*.2+i)*dt*.025});pillars.forEach(p=>{p.f.scale.y=.8+Math.sin(t*4+p.offset)*.18;p.light.intensity=8+Math.sin(t*5+p.offset)*2});emberLight.intensity=32+Math.sin(t*3)*5;
player.visor.material.emissiveIntensity=state.invuln>0?4:2.6;
if(state.running){state.elapsed+=dt;state.attackCd=Math.max(0,state.attackCd-dt);state.dodgeCd=Math.max(0,state.dodgeCd-dt);state.healCd=Math.max(0,state.healCd-dt);state.invuln=Math.max(0,state.invuln-dt);state.dodge=Math.max(0,state.dodge-dt);
const move=getMove(),speed=state.dodge>0?12:4.7;player.root.position.x=THREE.MathUtils.clamp(player.root.position.x+move.x*speed*dt,-4.25,4.25);player.root.position.z=THREE.MathUtils.clamp(player.root.position.z+move.y*speed*dt,-1.3,6.1);if(Math.hypot(move.x,move.y)>.05){player.root.rotation.y=Math.atan2(move.x,-move.y);player.legs[0].rotation.x=Math.sin(t*12)*.55;player.legs[1].rotation.x=-Math.sin(t*12)*.55}else{player.legs.forEach(l=>l.rotation.x*=.8)}
player.body.position.y=state.dodge>0?Math.sin((.43-state.dodge)/.43*Math.PI)*.34:Math.sin(t*2)*.025;player.body.rotation.x=state.attackCd>.28?-.12:0;player.arms[1].rotation.x=THREE.MathUtils.damp(player.arms[1].rotation.x,0,10,dt);player.sword.rotation.x=THREE.MathUtils.damp(player.sword.rotation.x,0,9,dt);player.root.rotation.y=THREE.MathUtils.damp(player.root.rotation.y,Math.atan2(boss.root.position.x-player.root.position.x,-(boss.root.position.z-player.root.position.z)),3,dt);
if(state.bossMode==='idle'){state.bossTimer-=dt;boss.root.position.x=Math.sin(t*.55)*.32;boss.body.position.y=2+Math.sin(t*1.8)*.055;if(state.bossTimer<=0){state.bossMode='tell';state.bossTell=state.phase===1?1.35:.95;danger.position.set(boss.root.position.x,.08,boss.root.position.z+.35);danger.visible=true;ui.phase.textContent='⚠ PREPARE-SE — GOLPE IMINENTE';}}
else if(state.bossMode==='tell'){state.bossTell-=dt;boss.arms[0].rotation.x=-.55-Math.sin(t*13)*.08;boss.arms[1].rotation.x=-.55-Math.sin(t*13)*.08;boss.body.scale.y=1+.025*Math.sin(t*18);if(state.bossTell<=0){state.bossMode='strike';danger.visible=false;const dist=Math.hypot(player.root.position.x-boss.root.position.x,player.root.position.z-boss.root.position.z+.25);shockRing(boss.root.position.clone().add(new THREE.Vector3(0,0,.4)),state.phase===2?0xff653b:0xff3d50,state.phase===2?3.4:2.8);if(dist<(state.phase===2?3.55:3.05)&&state.invuln<=0){const dmg=state.phase===2?24:19;state.hp=Math.max(0,state.hp-dmg);state.invuln=.6;player.root.position.z+=.45;burst(player.root.position.clone().add(new THREE.Vector3(0,1,0)),0xff3c54,15,2);announce('GOLPE RECEBIDO');updateUI();if(state.hp<=0){endGame(false)}}state.bossMode='recover';state.bossRecovery=state.phase===1?1.35:.98;boss.arms.forEach(a=>a.rotation.x=1.05);}}
else if(state.bossMode==='recover'){state.bossRecovery-=dt;boss.body.scale.y=THREE.MathUtils.damp(boss.body.scale.y,1,5,dt);boss.arms.forEach(a=>a.rotation.x=THREE.MathUtils.damp(a.rotation.x,0,4,dt));if(state.bossRecovery<=0){state.bossMode='idle';state.bossTimer=state.phase===1?2.45:1.75;}}
if(state.invuln>0)player.root.visible=Math.floor(t*18)%2===0;else player.root.visible=true;
if(state.bossHp<55&&state.phase===1){state.phase=2;state.bossTimer=1;announce('FASE II — COROA ARDENTE');}
}

